package com.oms.order.service;

import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import java.time.*;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.RefundValues.*;

/** Ordinary official refund API only. Fixed windows and one bounded page per message, independent of JDP. */
@Service public class RefundApiSupplement {
 @Resource RefundService refunds;
 @Resource RefundPlatformExecution platform;
 private OrderRepository r(){return refunds.repository;}
 public void scan(String c){if(r().messaging()==null)return;refunds.tx().execute(tx->{for(Map<String,Object> cursor:r().db().query("SELECT channel_id,work_version FROM oms_refund_api_cursor a WHERE a.company_code=? AND a.enabled=1 AND a.next_run<=NOW() AND (a.lease_until IS NULL OR a.lease_until<NOW()) AND NOT EXISTS(SELECT 1 FROM oms_message_outbox o WHERE o.company_code=a.company_code AND o.service_code='order' AND o.message_type='REFUND_API_PULL' AND o.business_id=CAST(a.channel_id AS CHAR) AND o.business_version=a.work_version AND o.process_state IN ('PENDING','WAITING','PROCESSING')) ORDER BY a.next_run,a.channel_id LIMIT 5 FOR UPDATE",ROW,c)){long channel=number(cursor,"channel_id"),version=number(cursor,"work_version")+1;r().db().update("UPDATE oms_refund_api_cursor SET work_version=?,next_run=DATE_ADD(NOW(),INTERVAL 120 SECOND) WHERE company_code=? AND channel_id=?",version,c,channel);r().messaging().enqueue(c,"REFUND_API_PULL",channel,version,"REFAPI"+channel,channel+":"+version,0);}return null;});}
 public Map<String,Object> page(String c,long channel,long version){String lease=token();Map<String,Object> cursor=refunds.tx().execute(tx->{List<Map<String,Object>> rows=r().db().query("SELECT * FROM oms_refund_api_cursor WHERE company_code=? AND channel_id=? FOR UPDATE",ROW,c,channel);if(rows.isEmpty()||number(rows.get(0),"enabled")!=1||number(rows.get(0),"work_version")!=version)return m("ended",true);Map<String,Object> row=rows.get(0);if(r().db().update("UPDATE oms_refund_api_cursor SET lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 90 SECOND) WHERE company_code=? AND channel_id=? AND (lease_until IS NULL OR lease_until<NOW())",lease,c,channel)!=1)return m("busy",true);if(row.get("window_start")==null){LocalDateTime start=time(text(row,"cursor_time")).minusMinutes(2),end=LocalDateTime.now().minusSeconds(3).withNano(0);if(end.isAfter(start.plusHours(1)))end=start.plusHours(1);require(end.isAfter(start),"同步窗口尚未到期");r().db().update("UPDATE oms_refund_api_cursor SET window_start=?,window_end=?,page_no=1 WHERE company_code=? AND channel_id=?",start.format(TIME),end.format(TIME),c,channel);row.put("window_start",start.format(TIME));row.put("window_end",end.format(TIME));row.put("page_no",1);}return row;});if(Boolean.TRUE.equals(cursor.get("ended")))return m("state","DONE","message","普通接口同步已停止或已有新通知");if(Boolean.TRUE.equals(cursor.get("busy")))return m("state","WAITING","message","同店铺普通退款同步正在处理");
  try{Map<String,Object> scope=m("channel_id",channel,"refund_id","","refund_sn","","platform_tid","");Map<String,Object> args=m("fields","refund_id,tid,oid,seller_nick,status,created,modified,refund_fee,refund_phase,dispute_type,has_good_return,reason,desc,order_status","start_modified",cursor.get("window_start"),"end_modified",cursor.get("window_end"),"page_no",cursor.get("page_no"),"page_size",20,"type","fixed","use_has_next",true);Map<String,Object> response=platform.call(c,scope,"LIST",args,"","普通退款接口增量同步");require(response.containsKey("refunds")||response.containsKey("total_results")||response.containsKey("has_next"),"普通退款列表响应缺少分页信息，未推进游标");Object raw=response.get("refunds");if(raw instanceof Map)raw=obj(raw).get("refund");List<Map<String,Object>> rows=new ArrayList<>();if(raw instanceof Collection)for(Object item:(Collection<?>)raw)rows.add(obj(item));else if(raw instanceof Map)rows.add(obj(raw));require(rows.size()<=20,"普通退款接口单页数量超出限制");
   long total=number(response,"total_results"),page=number(cursor,"page_no");require(!rows.isEmpty()||total==0&&!Boolean.TRUE.equals(response.get("has_next")),"普通退款列表为空但仍有后续数据，未推进游标");boolean complete=response.containsKey("has_next")?Boolean.FALSE.equals(response.get("has_next")):rows.size()<20||total>0&&page*20>=total;require(page<=1000,"普通退款窗口分页过多，请缩小时间范围后核对");
   return refunds.tx().execute(tx->{require(r().db().queryForObject("SELECT COUNT(*) FROM oms_refund_api_cursor WHERE company_code=? AND channel_id=? AND work_version=? AND page_no=? AND lease_token=? AND lease_until>NOW() FOR UPDATE",Long.class,c,channel,version,page,lease)==1,"普通退款同步租约或分页已变化");Map<String,Map<String,Object>> known=new HashMap<>();if(!rows.isEmpty()){List<Object> localArgs=new ArrayList<>(Arrays.asList(c,channel));for(Map<String,Object> item:rows)localArgs.add(numeric(text(item,"refund_id")));for(Map<String,Object> local:r().db().query("SELECT id,refund_id,platform_tid,platform_oid,source_modified,payload FROM oms_platform_refund WHERE company_code=? AND channel_id=? AND source_state='VALID' AND refund_id IN ("+String.join(",",Collections.nCopies(rows.size(),"?"))+")",ROW,localArgs.toArray()))known.put(text(local,"refund_id"),local);}
     for(Map<String,Object> item:rows){String rid=numeric(text(item,"refund_id")),modified=required(item,"modified",19),json=encode(item),digest=hash(encode(new TreeMap<>(item)));numeric(text(item,"tid"));numeric(text(item,"oid"));Map<String,Object> local=known.get(rid);boolean covered=local!=null&&text(item,"tid").equals(text(local,"platform_tid"))&&text(item,"oid").equals(text(local,"platform_oid"))&&locallyCovered(local,item);r().db().update("INSERT INTO oms_refund_api_item(company_code,channel_id,refund_id,source_modified,list_hash,list_payload,state,platform_refund_id) VALUES (?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE state=IF(VALUES(state)='DONE','DONE',state),platform_refund_id=COALESCE(platform_refund_id,VALUES(platform_refund_id))",c,channel,rid,modified,digest,json,covered?"DONE":"PENDING",covered?local.get("id"):null);Map<String,Object> accepted=r().db().queryForMap("SELECT id,state FROM oms_refund_api_item WHERE company_code=? AND channel_id=? AND refund_id=? AND source_modified=? AND list_hash=?",c,channel,rid,modified,digest);long itemId=number(accepted,"id");if(r().messaging()!=null&&!"DONE".equals(text(accepted,"state")))r().messaging().enqueue(c,"REFUND_API_DETAIL",itemId,1,rid,itemId+":1",0);}

     if(complete)r().db().update("UPDATE oms_refund_api_cursor SET cursor_time=GREATEST(cursor_time,window_end),window_start=NULL,window_end=NULL,page_no=1,last_success=NOW(),last_error='',next_run=DATE_ADD(NOW(),INTERVAL 60 SECOND) WHERE company_code=? AND channel_id=? AND lease_token=?",c,channel,lease);else r().db().update("UPDATE oms_refund_api_cursor SET page_no=page_no+1,last_success=NOW(),last_error='',next_run=NOW() WHERE company_code=? AND channel_id=? AND lease_token=?",c,channel,lease);return m("state",complete?"DONE":"WAITING","message",complete?"普通退款列表窗口已接收，完整详情由独立任务保存，不改动JDP游标":"当前页已保存，继续固定时间窗口下一页");});
  }catch(RuntimeException failure){String reason=failure instanceof IllegalArgumentException?failure.getMessage():"普通退款接口暂不可用，原分页和游标未推进";r().db().update("UPDATE oms_refund_api_cursor SET last_error=?,next_run=DATE_ADD(NOW(),INTERVAL 120 SECOND) WHERE company_code=? AND channel_id=? AND lease_token=?",reason.substring(0,Math.min(500,reason.length())),c,channel,lease);return m("state","WAITING","message",reason);}finally{r().db().update("UPDATE oms_refund_api_cursor SET lease_token=NULL,lease_until=NULL WHERE company_code=? AND channel_id=? AND lease_token=?",c,channel,lease);}
 } public Map<String,Object> detail(String c,long itemId){Map<String,Object> item=r().db().query("SELECT * FROM oms_refund_api_item WHERE company_code=? AND id=?",ROW,c,itemId).stream().findFirst().orElseThrow(()->new IllegalArgumentException("普通退款详情任务不存在"));if("DONE".equals(text(item,"state")))return m("state","DONE","message","完整退款详情已保存");Map<String,Object> scope=m("channel_id",item.get("channel_id"),"refund_id",item.get("refund_id"),"refund_sn","","platform_tid",text(obj(item.get("list_payload")),"tid"));
   try{Map<String,Object> response=platform.call(c,scope,"DETAIL",m("refund_id",item.get("refund_id"),"fields",RefundPlatformExecution.FIELDS),"","普通退款详情任务"),payload=obj(response.get("refund"));require(text(item,"refund_id").equals(text(payload,"refund_id")),"普通退款详情编号与原列表不一致");Map<String,Object> listed=obj(item.get("list_payload"));require(text(listed,"tid").equals(text(payload,"tid"))&&text(listed,"oid").equals(text(payload,"oid")),"普通退款详情原订单身份与列表不一致");String seller=required(payload,"seller_nick",200),modified=required(payload,"modified",19);require(!time(modified).isBefore(time(text(item,"source_modified"))),"完整详情尚未更新到列表版本，保留任务稍后重试");Map<String,Object> source=m("refund_id",payload.get("refund_id"),"tid",payload.get("tid"),"oid",payload.get("oid"),"seller_nick",seller,"status",payload.get("status"),"modified",modified,"jdp_modified",current(),"source_kind","ORDINARY_API","jdp_response",encode(m("refund_get_response",m("refund",payload))));return refunds.tx().execute(tx->{Map<String,Object> saved=refunds.ingest(c,number(item,"channel_id"),seller,source,"普通退款详情任务");String outcome=text(saved,"outcome");if(Arrays.asList("INVALID","CONFLICT").contains(outcome)){r().db().update("UPDATE oms_refund_api_item SET state='FAILED',platform_refund_id=?,last_error='普通退款详情存在来源冲突，原文已保留，请核对' WHERE company_code=? AND id=?",saved.get("id"),c,itemId);return m("state","WAITING","message","普通退款来源冲突已保留，请核对原文");}r().db().update("UPDATE oms_refund_api_item SET state='DONE',platform_refund_id=?,last_error='' WHERE company_code=? AND id=?",saved.get("id"),c,itemId);return m("state","DONE","message","完整退款详情已保存，按店铺设置转业务退款");});}
   catch(RuntimeException failure){String message=failure instanceof IllegalArgumentException?failure.getMessage():"普通退款完整详情暂未取得，将保留原列表并稍后重试";r().db().update("UPDATE oms_refund_api_item SET state='FAILED',last_error=? WHERE company_code=? AND id=? AND state<>'DONE'",message.substring(0,Math.min(500,message.length())),c,itemId);return m("state","WAITING","message",message);}
 }

 // A matching second alone is insufficient: never hide changed money or application text in a sparse list.
 static boolean locallyCovered(Map<String,Object> local,Map<String,Object> listed){
  int timeOrder=time(text(local,"source_modified")).compareTo(time(text(listed,"modified")));if(timeOrder<0)return false;if(timeOrder>0)return true;
  if(!listed.containsKey("status")||!listed.containsKey("refund_fee"))return false;
  Map<String,Object> full=parse(text(local,"payload"));for(String key:Arrays.asList("status","refund_fee","has_good_return","refund_phase","dispute_type","reason","desc","seller_nick","created"))if(listed.containsKey(key)){if("refund_fee".equals(key)){if(money(listed.get(key)).compareTo(money(full.get(key)))!=0)return false;}else if(!text(listed,key).equals(text(full,key)))return false;}return true;
 }
}
